widget_def.init:
var cv=container.querySelector('#wd-cv'),ctx=cv.getContext('2d'),t=0,af=null;
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=110;
var lam=+container.querySelector('#wd-lam').value,amp=+container.querySelector('#wd-amp').value,frq=+container.querySelector('#wd-frq').value;
container.querySelector('#wd-vl').textContent=lam;container.querySelector('#wd-vv').textContent=(lam*frq).toFixed(1);
var k=2*Math.PI/lam,om=2*Math.PI*frq,scX=W/(lam*3),scY=40/amp;
ctx.clearRect(0,0,W,110);ctx.strokeStyle='rgba(255,255,255,0.08)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,55);ctx.lineTo(W,55);ctx.stroke();
ctx.strokeStyle='rgba(251,191,36,0.25)';ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(0,55-amp*scY);ctx.lineTo(W,55-amp*scY);ctx.stroke();ctx.beginPath();ctx.moveTo(0,55+amp*scY);ctx.lineTo(W,55+amp*scY);ctx.stroke();ctx.setLineDash([]);
ctx.strokeStyle='#3ab09e';ctx.lineWidth=2;ctx.beginPath();
for(var x=0;x<=W;x++){var y=55-amp*scY*Math.cos(k*x/scX-om*t);x===0?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.stroke();
t+=0.016;af=requestAnimationFrame(draw);}
['wd-lam','wd-amp','wd-frq'].forEach(function(id){container.querySelector('#'+id).addEventListener('input',function(){cancelAnimationFrame(af);draw();});});draw();

var cv=container.querySelector('#so-cv'),ctx=cv.getContext('2d');
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=120;
var f=+container.querySelector('#so-f').value,al=+container.querySelector('#so-a').value,alf=al*f;
container.querySelector('#so-vd').textContent=(6/alf).toFixed(1);container.querySelector('#so-va').textContent=alf.toFixed(2);
ctx.clearRect(0,0,W,120);var pL=36,pR=8,pT=10,pB=22,sH=120-pT-pB,sW=W-pL-pR,maxD=15;
ctx.strokeStyle='#1f2937';ctx.lineWidth=1;[0,20,40,60].forEach(function(db){var y=pT+(db/60)*sH;ctx.beginPath();ctx.moveTo(pL,y);ctx.lineTo(W-pR,y);ctx.stroke();});
ctx.strokeStyle='#374151';ctx.beginPath();ctx.moveTo(pL,pT);ctx.lineTo(pL,pT+sH);ctx.lineTo(W-pR,pT+sH);ctx.stroke();
ctx.fillStyle='#6b7280';ctx.font='9px monospace';ctx.textAlign='right';
[0,-20,-40,-60].forEach(function(db,i){ctx.fillText(db+'dB',pL-3,pT+i*sH/3+3);});
ctx.textAlign='center';[0,5,10,15].forEach(function(d){ctx.fillText(d+'cm',pL+d*sW/maxD,pT+sH+13);});
var grd=ctx.createLinearGradient(pL,0,W-pR,0);grd.addColorStop(0,'rgba(58,176,158,0.35)');grd.addColorStop(1,'rgba(58,176,158,0.02)');
ctx.beginPath();ctx.moveTo(pL,pT);
for(var x=0;x<=sW;x++){var db=-alf*(x/sW*maxD);if(db<-65)break;ctx.lineTo(pL+x,pT+(-db/60)*sH);}
ctx.lineTo(pL+sW*(Math.min(6/alf,maxD)/maxD),pT+sH);ctx.lineTo(pL,pT+sH);ctx.closePath();ctx.fillStyle=grd;ctx.fill();
ctx.strokeStyle='#3ab09e';ctx.lineWidth=2;ctx.beginPath();var first=true;
for(var x=0;x<=sW;x++){var db=-alf*(x/sW*maxD);if(db<-65)break;var y=pT+(-db/60)*sH;first?(ctx.moveTo(pL+x,y),first=false):ctx.lineTo(pL+x,y);}ctx.stroke();
var d6=6/alf;if(d6<=maxD){var xd6=pL+d6*sW/maxD;ctx.strokeStyle='rgba(251,191,36,0.7)';ctx.lineWidth=1;ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(xd6,pT);ctx.lineTo(xd6,pT+sH);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#fbbf24';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('-6dB',xd6,pT+8);}
}['so-f','so-a'].forEach(function(id){container.querySelector('#'+id).addEventListener('input',draw);});draw();

var cv=container.querySelector('#em-cv'),ctx=cv.getContext('2d');
var REG=[{n:"Rayons γ",l:0,r:0.01,c:"#a78bfa",a:"Scintigraphie, radiothérapie"},
{n:"Rayons X",l:0.01,r:10,c:"#60a5fa",a:"Radiologie, CT-scan, DRXP"},
{n:"UV-C",l:10,r:280,c:"#818cf8",a:"Stérilisation UV-C"},
{n:"UV-B",l:280,r:320,c:"#8b5cf6",a:"Synthèse vitamine D"},
{n:"UV-A",l:320,r:400,c:"#a855f7",a:"PUVA thérapie"},
{n:"Visible",l:400,r:780,c:"#f59e0b",a:"Photothérapie, spectro UV/Vis"},
{n:"Infrarouge",l:780,r:1e6,c:"#ef4444",a:"IRTF, thermographie"},
{n:"Micro-ondes",l:1e6,r:1e9,c:"#f97316",a:"Hyperthermie, stérilisation"},
{n:"Radio / IRM",l:1e9,r:1e15,c:"#84cc16",a:"IRM (radiofréquences)"}];
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=70;
ctx.clearRect(0,0,W,70);
var g=ctx.createLinearGradient(0,0,W,0);g.addColorStop(0,'#a78bfa');g.addColorStop(0.2,'#60a5fa');g.addColorStop(0.4,'#f59e0b');g.addColorStop(0.6,'#ef4444');g.addColorStop(0.8,'#f97316');g.addColorStop(1,'#84cc16');
