var cv=container.querySelector('#ra-cv'),ctx=cv.getContext('2d');
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=120;
var t12=+container.querySelector('#ra-t').value,A0=+container.querySelector('#ra-a0').value;
var lam=Math.log(2)/t12,tMax=t12*6;
container.querySelector('#ra-v5').textContent=(A0*Math.exp(-lam*t12*5)).toFixed(2);
ctx.clearRect(0,0,W,120);var pL=38,pR=8,pT=8,pB=22,sH=120-pT-pB,sW=W-pL-pR;
ctx.strokeStyle='#1f2937';ctx.lineWidth=1;[0,1,2,3].forEach(function(i){var y=pT+i*sH/3;ctx.beginPath();ctx.moveTo(pL,y);ctx.lineTo(W-pR,y);ctx.stroke();});
ctx.strokeStyle='#374151';ctx.beginPath();ctx.moveTo(pL,pT);ctx.lineTo(pL,pT+sH);ctx.lineTo(W-pR,pT+sH);ctx.stroke();
ctx.fillStyle='#6b7280';ctx.font='9px monospace';ctx.textAlign='right';['100%','67%','33%','0%'].forEach(function(l,i){ctx.fillText(l,pL-3,pT+i*sH/3+3);});
ctx.textAlign='center';[1,2,3,4,5,6].forEach(function(k){ctx.fillText(k+'t½',pL+k*sW/6,pT+sH+13);});
var grd=ctx.createLinearGradient(pL,0,W-pR,0);grd.addColorStop(0,'rgba(58,176,158,0.3)');grd.addColorStop(1,'rgba(58,176,158,0.02)');
ctx.beginPath();ctx.moveTo(pL,pT);
for(var x=0;x<=sW;x++){var t=x/sW*tMax,A=A0*Math.exp(-lam*t);ctx.lineTo(pL+x,pT+sH*(1-A/A0));}
ctx.lineTo(W-pR,pT+sH);ctx.lineTo(pL,pT+sH);ctx.closePath();ctx.fillStyle=grd;ctx.fill();
ctx.strokeStyle='#3ab09e';ctx.lineWidth=2;ctx.beginPath();
for(var x=0;x<=sW;x++){var t=x/sW*tMax,A=A0*Math.exp(-lam*t);x===0?ctx.moveTo(pL,pT+sH*(1-A/A0)):ctx.lineTo(pL+x,pT+sH*(1-A/A0));}ctx.stroke();
ctx.strokeStyle='rgba(251,191,36,0.5)';ctx.lineWidth=1;ctx.setLineDash([3,3]);
[1,2,3].forEach(function(k){var xk=pL+k*sW/6;ctx.beginPath();ctx.moveTo(xk,pT);ctx.lineTo(xk,pT+sH);ctx.stroke();
ctx.fillStyle='rgba(251,191,36,0.7)';ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText(k+'t½',xk,pT+7);});ctx.setLineDash([]);}
