ctx.fillStyle='rgba(30,58,138,0.3)';ctx.fillRect(0,0,mX-8,90);ctx.fillStyle='rgba(22,101,52,0.3)';ctx.fillRect(mX+8,0,W-mX-8,90);
ctx.fillStyle='rgba(251,191,36,0.35)';ctx.fillRect(mX-8,0,16,90);
ctx.fillStyle='#93c5fd';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('Ext.',mX/2,14);ctx.fillText(cOut+' mM',mX/2,27);
ctx.fillStyle='#86efac';ctx.fillText('Int.',mX+W/4,14);ctx.fillText(cIn+' mM',mX+W/4,27);
var eC=E>0?'#f97316':E<-60?'#60a5fa':'#3ab09e';ctx.fillStyle=eC;ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(E.toFixed(1)+' mV',mX,55);
var norm=Math.max(-1,Math.min(1,E/120));var arL=25;ctx.strokeStyle=eC;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(mX,65);ctx.lineTo(mX+norm*arL,65);ctx.stroke();if(norm!==0){ctx.fillStyle=eC;var arX=mX+norm*arL,arDir=norm>0?1:-1;ctx.beginPath();ctx.moveTo(arX,60);ctx.lineTo(arX+arDir*5,65);ctx.lineTo(arX,70);ctx.fill();}}
['ne-ion','ne-out','ne-in'].forEach(function(id){container.querySelector('#'+id).addEventListener('input',draw);});draw();

var root=container.querySelector('#osc-panel'),tabsEl=container.querySelector('#osc-tabs');
var TABS=['Osmolarité calculée','Trou osmolaire','Perfusion (voie)'];
var cur=0;
function tabHtml(){return TABS.map(function(t,i){return '<button onclick="window.__oscSet&&window.__oscSet('+i+')" style="padding:5px 9px;border-radius:7px;border:1px solid '+(i===cur?'#3ab09e':'rgba(255,255,255,.15)')+';background:'+(i===cur?'rgba(58,176,158,.18)':'#111827')+';color:'+(i===cur?'#3ab09e':'#9ca3af')+';font-size:11px;cursor:pointer">'+t+'</button>';}).join('');}
function row(lbl,id,min,max,val,step,unit){return '<div style="margin-top:6px"><div style="font-size:10px;color:#9ca3af;text-transform:uppercase;letter-spacing:.6px">'+lbl+' <span id="'+id+'-l" style="color:#3ab09e">'+val+'</span> '+unit+'</div><input type="range" id="'+id+'" min="'+min+'" max="'+max+'" value="'+val+'" step="'+step+'" style="width:100%;accent-color:#3ab09e;cursor:pointer"></div>';}
function box(inner){return '<div style="background:#111827;border:1px solid rgba(58,176,158,.25);border-radius:8px;padding:10px">'+inner+'</div>';}
function bigval(id,unit){return '<div style="text-align:center;margin:8px 0"><span id="'+id+'" style="font-size:30px;font-weight:800;color:#3ab09e">–</span> <span style="color:#9ca3af;font-size:12px">'+unit+'</span></div>';}

function render(){
  tabsEl.innerHTML=tabHtml();
  if(cur===0){
    root.innerHTML=box(
      row('[Na⁺]','osc-na',110,175,140,1,'mmol/L')+
      row('[Glucose]','osc-glu',2,40,5,0.5,'mmol/L')+
      row('[Urée]','osc-ur',1,50,5,0.5,'mmol/L')+
      bigval('osc-out','mOsm/L')+
      '<div id="osc-tonic" style="text-align:center;font-size:11px;padding:5px;border-radius:6px"></div>'+
      '<div style="font-size:9px;color:#6b7280;margin-top:6px;text-align:center">Osm = 2·[Na⁺] + [Glucose] + [Urée]  (tout en mmol/L)</div>');
    bind(['osc-na','osc-glu','osc-ur'],calc0);calc0();
  } else if(cur===1){
    root.innerHTML=box(
      '<div style="font-size:10px;color:#9ca3af;margin-bottom:4px">Osmolarité MESURÉE (osmomètre)</div>'+
      row('Mesurée','osc-meas',260,360,295,1,'mOsm/kg')+
      '<div style="font-size:10px;color:#9ca3af;margin-top:8px">Osmolarité CALCULÉE</div>'+
      row('[Na⁺]','osc-na2',110,175,140,1,'mmol/L')+
      row('[Glucose]','osc-glu2',2,40,5,0.5,'mmol/L')+
      row('[Urée]','osc-ur2',1,50,5,0.5,'mmol/L')+
      bigval('osc-gap','mOsm/kg (trou)')+
      '<div id="osc-gapint" style="text-align:center;font-size:11px;padding:6px;border-radius:6px"></div>'+
      '<div style="font-size:9px;color:#6b7280;margin-top:6px;text-align:center">Trou > 10 → suspecter alcool toxique (méthanol, éthylène-glycol), éthanol, cétoacidose</div>');
    bind(['osc-meas','osc-na2','osc-glu2','osc-ur2'],calc1);calc1();
  } else {
    root.innerHTML=box(
      row('Osmolarité de la solution','osc-perf',250,2000,308,1,'mOsm/L')+
      bigval('osc-perfout','mOsm/L')+
      '<div id="osc-perfint" style="text-align:center;font-size:11px;padding:6px;border-radius:6px"></div>'+
      '<div style="font-size:9px;color:#6b7280;margin-top:6px;line-height:1.5">• ≤ 600–900 mOsm/L : voie périphérique possible<br>• > 900 mOsm/L : voie centrale recommandée<br>Réf : NaCl 0,9% = 308 · G5% = 278 · G10% = 555 · NaCl 3% = 1027</div>');
    bind(['osc-perf'],calc2);calc2();
  }
}
function bind(ids,fn){ids.forEach(function(id){var e=container.querySelector('#'+id);if(e)e.addEventListener('input',fn);});}
function setL(id,v){var e=container.querySelector('#'+id+'-l');if(e)e.textContent=v;}
function calc0(){
  var na=+container.querySelector('#osc-na').value,gl=+container.querySelector('#osc-glu').value,ur=+container.querySelector('#osc-ur').value;
  setL('osc-na',na);setL('osc-glu',gl);setL('osc-ur',ur);
  var osm=2*na+gl+ur;container.querySelector('#osc-out').textContent=Math.round(osm);
  var el=container.querySelector('#osc-tonic');
  if(osm<275){el.textContent='Hypo-osmolaire (< 275)';el.style.background='rgba(96,165,250,.15)';el.style.color='#60a5fa';}
  else if(osm<=295){el.textContent='Normal (275–295 mOsm/L)';el.style.background='rgba(58,176,158,.15)';el.style.color='#3ab09e';}
  else{el.textContent='Hyper-osmolaire (> 295)';el.style.background='rgba(248,113,113,.15)';el.style.color='#f87171';}
}
function calc1(){
  var meas=+container.querySelector('#osc-meas').value,na=+container.querySelector('#osc-na2').value,gl=+container.querySelector('#osc-glu2').value,ur=+container.querySelector('#osc-ur2').value;
  setL('osc-meas',meas);setL('osc-na2',na);setL('osc-glu2',gl);setL('osc-ur2',ur);
  var calc=2*na+gl+ur,gap=meas-calc;container.querySelector('#osc-gap').textContent=Math.round(gap);
  var el=container.querySelector('#osc-gapint');
  if(gap<=10){el.textContent='Trou normal (≤ 10)';el.style.background='rgba(58,176,158,.15)';el.style.color='#3ab09e';}
  else if(gap<=20){el.textContent='⚠ Trou élevé (10–20) — surveiller';el.style.background='rgba(251,191,36,.15)';el.style.color='#fbbf24';}
  else{el.textContent='🚨 Trou très élevé (> 20) — intoxication probable';el.style.background='rgba(248,113,113,.15)';el.style.color='#f87171';}
}
function calc2(){
  var o=+container.querySelector('#osc-perf').value;setL('osc-perf',o);
  container.querySelector('#osc-perfout').textContent=Math.round(o);
  var el=container.querySelector('#osc-perfint');
  if(o<=600){el.textContent='Voie périphérique : OK';el.style.background='rgba(58,176,158,.15)';el.style.color='#3ab09e';}
  else if(o<=900){el.textContent='⚠ Périphérique tolérée avec précautions (débit, gros calibre)';el.style.background='rgba(251,191,36,.15)';el.style.color='#fbbf24';}
  else{el.textContent='🚨 Voie centrale recommandée (> 900 mOsm/L)';el.style.background='rgba(248,113,113,.15)';el.style.color='#f87171';}
}
window.__oscSet=function(i){cur=i;render();};
render();
